-- ============================================================
-- EX 603 reference dataset: Movie / TV Recommendation Database
-- Generated deterministically (seed 603). Do not edit by hand.
-- Load with:  createdb ex603_movies && psql -d ex603_movies -f movies.sql
-- ============================================================
-- PostgreSQL load:  createdb ex603_movies  &&  psql -d ex603_movies -f movies.sql
-- (Re-running is safe: every table is dropped first, children before parents.)
DROP TABLE IF EXISTS ratings CASCADE;
DROP TABLE IF EXISTS movie_genres CASCADE;
DROP TABLE IF EXISTS movie_languages CASCADE;
DROP TABLE IF EXISTS genres CASCADE;
DROP TABLE IF EXISTS movies CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- ---------- actor ----------
CREATE TABLE users (
    user_id        INT           NOT NULL,
    user_name      VARCHAR(120)  NOT NULL,
    signup_date      DATE          NOT NULL,
    country    VARCHAR(80)   NOT NULL,
    email    VARCHAR(160)  NOT NULL,
    invited_by INT           NULL,
    is_active      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (user_id),
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT ck_users_no_self CHECK (invited_by IS NULL OR invited_by <> user_id),
    CONSTRAINT fk_users_ref FOREIGN KEY (invited_by)
        REFERENCES users (user_id) ON DELETE SET NULL
);

-- ---------- producer ----------
CREATE TABLE movies (
    movie_id        INT           NOT NULL,
    title      VARCHAR(120)  NOT NULL,
    added_on      DATE          NOT NULL,
    origin_country    VARCHAR(80)   NOT NULL,
    imdb_code    VARCHAR(60)   NOT NULL,
    release_year    SMALLINT NOT NULL,
    is_available      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (movie_id),
    CONSTRAINT uq_movies_imdb_code UNIQUE (imdb_code),
    CONSTRAINT ck_movies_metric CHECK (release_year >= 1900 AND release_year <= 2100)
);

-- ---------- multivalued attribute, resolved ----------
CREATE TABLE movie_languages (
    movie_id   INT       NOT NULL,
    language_code  CHAR(2) NOT NULL,
    PRIMARY KEY (movie_id, language_code),
    CONSTRAINT fk_movie_languages_owner FOREIGN KEY (movie_id)
        REFERENCES movies (movie_id) ON DELETE CASCADE
);

-- ---------- catalog ----------
CREATE TABLE genres (
    genre_id    INT          NOT NULL,
    genre_name  VARCHAR(60)  NOT NULL,
    genre_description  VARCHAR(200) NULL,
    PRIMARY KEY (genre_id),
    CONSTRAINT uq_genres_name UNIQUE (genre_name)
);

-- ---------- junction: producer to catalog, composite PK ----------
CREATE TABLE movie_genres (
    movie_id   INT  NOT NULL,
    genre_id   INT  NOT NULL,
    tagged_on DATE NOT NULL,
    PRIMARY KEY (movie_id, genre_id),
    CONSTRAINT fk_movie_genres_prod FOREIGN KEY (movie_id)
        REFERENCES movies (movie_id) ON DELETE CASCADE,
    CONSTRAINT fk_movie_genres_cat FOREIGN KEY (genre_id)
        REFERENCES genres (genre_id) ON DELETE RESTRICT
);

-- ---------- event: the high volume fact table ----------
CREATE TABLE ratings (
    rating_id       BIGINT        NOT NULL,
    user_id       INT           NOT NULL,
    movie_id       INT           NOT NULL,
    rated_at       TIMESTAMP      NOT NULL,
    reviewed_at      TIMESTAMP      NULL,
    device_country   VARCHAR(80),
    score   DECIMAL(2,1) NOT NULL,
    watch_minutes   DECIMAL(7,2) NOT NULL,
    weight    DECIMAL(4,2)  NOT NULL DEFAULT 1.00,
    rating_status   VARCHAR(20)   NOT NULL,
    withdrawn_reason   VARCHAR(60)   NULL,     -- nullable by design
    PRIMARY KEY (rating_id),
    CONSTRAINT ck_ratings_metric_pos  CHECK (score >= 0),
    CONSTRAINT ck_ratings_second_pos  CHECK (watch_minutes > 0),
    CONSTRAINT ck_ratings_third_min   CHECK (weight >= 1.00),
    CONSTRAINT ck_ratings_time_order  CHECK (reviewed_at IS NULL OR reviewed_at >= rated_at),
    CONSTRAINT fk_ratings_actor FOREIGN KEY (user_id)
        REFERENCES users (user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ratings_prod FOREIGN KEY (movie_id)
        REFERENCES movies (movie_id) ON DELETE RESTRICT
);

